// Constants of this build; the rules they stand for are in README.md.
final class Config {
    private Config() {}

    static final String[] CRITERIA = {"arrive", "rides", "fare", "walk"};
    static final int MAX_RIDES = 3;
    static final int FARE_CAP = 450;
    static final int TRANSFER_WINDOW = 30;
    static final int TRANSFER_DISCOUNT = 60;
    static final int CHANGE_DEFAULT = 3;
    static final boolean HAS_NOWALK = true;
    static final boolean HAS_AVOID = true;
}

