// Constants of this build; the rules they stand for are in README.md.
final class Config {
    private Config() {}

    static final String[] CRITERIA = {"fare", "arrive", "rides", "walk"};
    static final int MAX_RIDES = 3;
    static final int FARE_CAP = 600;
    static final int TRANSFER_WINDOW = 35;
    static final int TRANSFER_DISCOUNT = 100;
    static final int CHANGE_DEFAULT = 3;
    static final boolean HAS_NOWALK = false;
    static final boolean HAS_AVOID = false;
}

